insert into public.guidance(id,category,event,title,body,institution,source_url,reviewed_at,visible) values('60000000-0000-4000-8000-000000000001','nature','Sismos','Prepararnos también es cuidarnos','Acuerda un plan familiar, identifica zonas seguras y prepara tu mochila de emergencia. Durante un sismo, conserva la calma y aléjate de ventanas y objetos que puedan caer.','INDECI','https://www.gob.pe/1053-que-hacer-en-caso-de-sismo','2026-11-06',true) on conflict(id) do nothing;
insert into public.guidance(id,category,event,title,body,institution,source_url,reviewed_at,visible) values('60000000-0000-4000-8000-000000000002','nature','Lluvias y El Niño','Ante la lluvia, evita exponerte','Mantente alejado de zonas inundadas y cauces de quebradas. Sigue la información de las autoridades y conoce las rutas de evacuación oficiales de tu comunidad.','SENAMHI','https://www.gob.pe/37201-recomendaciones-para-protegerte-de-las-lluvias-intensas','2026-11-06',true) on conflict(id) do nothing;
insert into public.guidance(id,category,event,title,body,institution,source_url,reviewed_at,visible) values('60000000-0000-4000-8000-000000000003','security','Seguridad ciudadana','Tu seguridad es lo primero','Ante un robo, prioriza ponerte a salvo y comunícate con la Policía. Aporta información concreta sobre lo ocurrido. Evita tocar objetos que puedan conservar evidencias.','MININTER','https://www.gob.pe/institucion/mininter/pages/706-presentar-una-denuncia-por-robo','2026-11-06',true) on conflict(id) do nothing;
insert into public.services(id,title,category,description,phone,source_url,reviewed_at) values('police','Policía Nacional del Perú','Seguridad','Canal oficial para comunicar emergencias policiales. Cobertura nacional; disponibilidad de atención local no comprobada por la app.','105','https://www.gob.pe/institucion/mininter/pages/706-presentar-una-denuncia-por-robo','2026-11-06') on conflict(id) do nothing;
insert into public.services(id,title,category,description,source_url,reviewed_at) values('indeci','Orientación de INDECI','Preparación','Información oficial sobre preparación ante emergencias y desastres. No es un servicio de despacho o rescate desde esta aplicación.','https://www.gob.pe/10148-recibir-informacion-u-orientacion-sobre-preparacion-ante-emergencias-y-desastres','2026-11-06') on conflict(id) do nothing;
